1	// config-to-document — the page's edit mode ("Edit" button in the top bar).
2	//
3	// A consultant or key user corrects the consultant notes and the reference
4	// panel, the value tables (card title, cells, rows) and the change history in
5	// the finished document, with nothing installed and nothing loaded from the
6	// network. Edited views carry an "Edited" badge; their SM30 drawings are drawn
7	// again from the edited rows at the next build.
8	//   · click a text to change it (plain text); add or delete list items, add
9	//     notes to an activity that has none, delete a source
10	//   · replace a drawn SM30 screen with a real screenshot (button, or Ctrl+V on the
11	//     selected drawing) and back to the drawing
12	//   · undo every change (Ctrl+Z outside a text field, or the Undo button),
13	//     autosave to the browser (IndexedDB) with "continue editing" on reopen
14	//   · "Save" asks for author and change note and downloads the page again with
15	//     every edited note embedded (<script id="config-edits">);
16	//     `build-config-doc.mjs --import <file>` merges them into notes/edits.json,
17	//     so the next version keeps the edits.
18	//
19	// Edits replace the whole note of an activity and are system-specific: the
20	// knowledge base (notes.mjs kb) never takes them.
21	
22	const LABELS = {
23	  ko: {
24	    image: '캡처로 교체', restore: '원래 화면',
25	    addRow: '+ 행 추가', delRow: '행 삭제', svgStale: '화면 그림은 다음 빌드(--import) 때 고친 값으로 다시 그려집니다.',
26	    edit: '편집', done: '편집 종료', save: '저장', undo: '되돌리기', add: '+ 항목 추가', del: '삭제', newNote: '+ 해설 추가',
27	    edited: '편집됨', draft: '저장하지 않은 편집이 있습니다', resume: '이어서 편집', discard: '버리기', unsaved: '저장하지 않은 변경이 있습니다.',
28	    saveTitle: '저장 — 변경 기록', author: '작성자', note: '변경 내용', noteDefault: '편집 모드에서 해설 수정', needAuthor: '작성자를 입력하세요.',
29	    ok: '저장', cancel: '취소', saved: '저장했습니다. 받은 HTML 파일을 담당 컨설턴트에게 보내 주세요.', placeholder: '내용을 입력하세요',
30	    hint: '편집 모드: 해설 · 참고자료 · 설정값 표 · 변경 이력의 글자를 클릭해 고칩니다. 고친 표에는 "편집됨"이 붙어 시스템 값과 다르다는 것이 보입니다. 화면 그림을 클릭한 뒤 Ctrl+V 하면 실제 캡처로 바뀝니다.',
31	  },
32	  en: {
33	    image: 'Use screenshot', restore: 'Original screen',
34	    addRow: '+ Add row', delRow: 'Delete row', svgStale: 'The screen drawing shows the edited values from the next build (--import).',
35	    edit: 'Edit', done: 'Done', save: 'Save', undo: 'Undo', add: '+ Add item', del: 'Delete', newNote: '+ Add notes',
36	    edited: 'Edited', draft: 'You have unsaved edits', resume: 'Continue editing', discard: 'Discard', unsaved: 'You have unsaved changes.',
37	    saveTitle: 'Save — change record', author: 'Author', note: 'Change', noteDefault: 'Notes edited in edit mode', needAuthor: 'Enter the author.',
38	    ok: 'Save', cancel: 'Cancel', saved: 'Saved. Send the downloaded HTML file to your consultant.', placeholder: 'Type here',
39	    hint: 'Edit mode: click any text of the notes, the reference panel, the value tables or the change history to change it. Edited tables carry an "Edited" badge, so readers see they differ from the system. Click a screen drawing and press Ctrl+V to use a real screenshot instead.',
40	  },
41	};
42	export const editorLabels = (lang) => LABELS[String(lang || '').slice(0, 2).toLowerCase()] || LABELS.en;
