44	export const EDITOR_STYLE = `
45	body.editing .ed{outline:1px dashed #9bb3cc;outline-offset:2px;border-radius:3px;cursor:text;min-width:2em;display:inline-block}
46	body.editing .ed:empty::before{content:attr(data-ph);color:var(--mute)}
47	body.editing .ed:focus{outline:2px solid #0a6ed1;background:#fff}
48	body.editing p.ed{display:block}
49	body.editing td.ed,body.editing th.ed{display:table-cell;outline-offset:-2px;border-radius:0;min-width:0}
50	body.editing table.vals td.ed{max-width:none;overflow:visible;white-space:pre-wrap}
51	.edx{border:0;background:none;color:var(--blocked);cursor:pointer;font-size:11px;padding:0 4px;margin-left:4px}
52	.edadd{border:1px dashed var(--line);background:#fff;color:var(--ink2);border-radius:6px;font:inherit;font-size:11.5px;padding:2px 9px;cursor:pointer;margin:2px 0 8px}
53	.edbadge{color:#7a4fb5;background:#efe6fa}
54	.shotbar{display:none;gap:6px;margin:6px 0 4px}body.editing .shotbar{display:flex}
55	body.editing .mock{cursor:pointer}body.editing .mock.ce-sel{outline:2px solid #0a6ed1;outline-offset:2px}
56	.ce-bar{display:none;position:sticky;top:0;z-index:5;background:#fff8dc;border-bottom:1px solid #e8d9a0;color:#6b5a1f;font-size:12.5px;padding:7px 34px}
57	body.editing .ce-bar{display:block}
58	#ce-undo,#ce-save{display:none}body.editing #ce-undo,body.editing #ce-save{display:inline-block}
59	.ce-modal{position:fixed;inset:0;background:rgba(10,20,32,.5);display:flex;align-items:center;justify-content:center;z-index:60}
60	.ce-modal div{background:#fff;border-radius:8px;padding:18px 20px;width:min(420px,92vw)}
61	.ce-modal h3{margin:0 0 12px;font-size:15px}.ce-modal label{display:block;font-size:12.5px;margin:8px 0 3px;color:var(--ink2)}
62	.ce-modal input,.ce-modal textarea{width:100%;font:inherit;padding:6px 9px;border:1px solid var(--line);border-radius:6px}
63	.ce-modal .btns{display:flex;gap:8px;justify-content:flex-end;margin-top:14px}
64	.ce-modal button{font:inherit;border:1px solid var(--line);background:#fff;border-radius:6px;padding:5px 12px;cursor:pointer}
65	.ce-modal button.pri{background:var(--ink);color:#fff;border-color:var(--ink)}
66	.ce-draft{position:fixed;bottom:16px;left:50%;transform:translateX(-50%);background:var(--ink);color:#fff;border-radius:8px;padding:10px 14px;z-index:55;display:flex;gap:10px;align-items:center;font-size:13px}
67	.ce-draft button{font:inherit;font-size:12.5px;border:1px solid #4b6a8a;background:none;color:#fff;border-radius:6px;padding:3px 10px;cursor:pointer}
68	@media print{.edx,.edadd,.ce-bar{display:none!important}}
69	`;
