71	// Runs inside the page script's closure: uses D, T, $, esc, cur, show, renderTree.
72	// The page's renderers call F() / FL() / EDIT to draw editable fields.
73	export const EDITOR_SCRIPT = String.raw`
74	const EL=D.EL;let EDIT=false;let dirty=false;const undo=[];const touched=new Set();
75	const CE=(()=>{try{return JSON.parse(document.getElementById('config-edits').textContent||'{}')}catch(e){return {}}})();
76	CE.edits=CE.edits||{};CE.log=CE.log||[];
77	// Diagrams are drawn at build time: an embedded edit keeps the drawing of an unchanged flow.
78	const keepSvg=(n,o)=>{for(const [i,c] of ((n&&n.cases&&n.cases.list)||[]).entries()){const p=o&&o.cases&&o.cases.list[i];if(!c.svg&&p&&JSON.stringify(p.flow)===JSON.stringify(c.flow))c.svg=p.svg}return n};
79	D.notes=D.notes||{};for(const [k,v] of Object.entries(CE.edits))if(v)D.notes[k]=keepSvg(v,D.notes[k]);
80	// Each note as the page opened it, to drop changes that were undone back to it.
81	const bare=n=>n?JSON.stringify({...n,edited:undefined}):null;const orig={};
82	// Views: values, card title and change history; same lifecycle as the notes.
83	CE.views=CE.views||{};const VF=['rows','cust','trOf','cardTitle','histList','shots'];const vtouched=new Set();const vorig={};
84	const vbare=k=>{const v=D.views[k];return v?JSON.stringify(Object.fromEntries(VF.map(f=>[f,v[f]??null]))):null};
85	const vsnap=k=>{const v=D.views[k];return JSON.stringify({...JSON.parse(vbare(k)),edited:v.edited??null})};
86	const vapply=(k,e)=>{const v=D.views[k];if(!v||!e)return;for(const f of VF)if(e[f]!=null)v[f]=structuredClone(e[f]);v.edited=e.edited};
87	for(const [k,e] of Object.entries(CE.views)){const v=D.views[k];if(v&&e&&String(e.edited&&e.edited.at||'')>String(v.edited&&v.edited.at||''))v.svgStale=true;vapply(k,e)}
88	const F=(path,text,tag,cls)=>{tag=tag||'span';const c=[cls,EDIT?'ed':''].filter(Boolean).join(' ');return '<'+tag+(c?' class="'+c+'"':'')+(EDIT?' contenteditable="plaintext-only" spellcheck="false" data-ph="'+esc(EL.placeholder)+'" data-a="'+esc(cur)+'" data-ef="'+esc(path)+'"':'')+'>'+esc(text)+'</'+tag+'>'};
89	const FL=(path,list,cls)=>{list=list||[];if(!EDIT)return list.length?'<ul'+(cls?' class="'+cls+'"':'')+'>'+list.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'';return '<ul'+(cls?' class="'+cls+'"':'')+'>'+list.map((x,i)=>'<li>'+F(path+'.'+i,x)+'<button class="edx" data-del="'+esc(path+'.'+i)+'" title="'+esc(EL.del)+'">✕</button></li>').join('')+'</ul><button class="edadd" data-add="'+esc(path)+'">'+esc(EL.add)+'</button>'};
90	const FV=(k,path,text,tag,cls)=>{tag=tag||'span';const c=[cls,EDIT?'ed':''].filter(Boolean).join(' ');return '<'+tag+(c?' class="'+c+'"':'')+(EDIT?' contenteditable="plaintext-only" spellcheck="false" data-ph="'+esc(EL.placeholder)+'" data-vk="'+esc(k)+'" data-ve="'+esc(path)+'"':'')+'>'+esc(text)+'</'+tag+'>'};
91	const shotTools=(k,key,has)=>EDIT?'<div class="shotbar"><button class="edadd" data-shot="'+esc(k)+'|'+esc(key)+'">🖼 '+esc(EL.image)+'</button>'+(has?'<button class="edadd" data-unshot="'+esc(k)+'|'+esc(key)+'">↺ '+esc(EL.restore)+'</button>':'')+'</div>':'';
92	const editedBadge=n=>n&&n.edited?'<span class="badge edbadge">'+esc(EL.edited)+(n.edited.author?' · '+esc(n.edited.author):'')+(n.edited.at?' · '+esc(new Date(n.edited.at).toLocaleDateString()):'')+'</span>':'';
93	const getAt=(o,p)=>p.split('.').reduce((x,k)=>x==null?x:x[k],o);
94	const setAt=(o,p,v)=>{const ks=p.split('.');const last=ks.pop();const t=ks.reduce((x,k)=>x[k]??(x[k]={}),o);t[last]=v};
95	const KEY='sc4sap-config-edit:'+location.pathname+':'+D.meta.system+':'+D.meta.module+':'+D.meta.extractedAt;
96	const idb=f=>new Promise(r=>{try{const q=indexedDB.open('sc4sap-config-doc',1);q.onupgradeneeded=()=>q.result.createObjectStore('drafts');q.onsuccess=()=>{try{const tx=q.result.transaction('drafts','readwrite');f(tx.objectStore('drafts'),r)}catch(e){r(null)}};q.onerror=()=>r(null)}catch(e){r(null)}});
97	const saveDraft=()=>idb((s,r)=>{const edits={};for(const id of touched)edits[id]=D.notes[id];const views={};for(const k of vtouched)views[k]=JSON.parse(vbare(k)||'null');const q=s.put({edits,views,at:Date.now()},KEY);q.onsuccess=()=>r(true);q.onerror=()=>r(false)});
98	const loadDraft=()=>idb((s,r)=>{const q=s.get(KEY);q.onsuccess=()=>r(q.result||null);q.onerror=()=>r(null)});
99	const dropDraft=()=>idb((s,r)=>{const q=s.delete(KEY);q.onsuccess=()=>r(true);q.onerror=()=>r(false)});
100	function rerender(){const m=$('#main').scrollTop,rf=$('#ref').scrollTop;const full=[...document.querySelectorAll('table.vals[data-full]')].map(t=>t.id.slice(3));cur?show(cur):home();for(const i of full)fullTable(i);$('#main').scrollTop=m;$('#ref').scrollTop=rf}
101	function change(id,fn){const before=D.notes[id]?JSON.stringify(D.notes[id]):null;if(!(id in orig))orig[id]=bare(D.notes[id]);fn();const n=D.notes[id];if(n)n.edited={...(n.edited||{}),at:new Date().toISOString()};undo.push({id,before});if(undo.length>300)undo.shift();touched.add(id);dirty=true;saveDraft()}
102	function changeV(k,fn){const v=D.views[k];if(!v)return;const before=vsnap(k);if(!(k in vorig))vorig[k]=vbare(k);fn(v);v.edited={...(v.edited||{}),at:new Date().toISOString()};v.svgStale=true;undo.push({vk:k,before});if(undo.length>300)undo.shift();vtouched.add(k);dirty=true;saveDraft()}
103	// A row added or deleted shifts the customer-row marks and their requests.
104	const shiftCust=(v,i,d)=>{const tr=v.trOf||{};const next={};v.cust=v.cust.filter(x=>d>0||x!==i).map(x=>x>=i+(d<0?1:0)?x+d:x);for(const [x,t] of Object.entries(tr)){const n=Number(x);if(d<0&&n===i)continue;next[n>=i+(d<0?1:0)?n+d:n]=t}v.trOf=next};
105	function setV(v,p,val){if(p==='title'){v.cardTitle=val;return}const [kind,a,b]=p.split('.');if(kind==='r'){v.rows[a][b]=val;return}if(!v.histList)v.histList=histOf(v).map(x=>({...x}));v.histList[a][b]=val}
106	document.addEventListener('focusin',e=>{const el=EDIT&&e.target.closest&&e.target.closest('[contenteditable][data-ve]');if(el)el.dataset.o=el.innerText});
107	document.addEventListener('focusout',e=>{const el=EDIT&&e.target.closest&&e.target.closest('[contenteditable][data-ve]');if(!el)return;const v=el.innerText.replace(/\u00a0/g,' ').replace(/\s+$/,'');if(v===(el.dataset.o??'').replace(/\s+$/,''))return;el.dataset.o=v;const p=el.dataset.ve;changeV(el.dataset.vk,x=>setV(x,p,v))});
108	document.addEventListener('keydown',e=>{const el=EDIT&&e.target.closest&&e.target.closest('[contenteditable][data-ve]');if(el&&e.key==='Enter'){e.preventDefault();el.blur()}});
109	document.addEventListener('click',e=>{if(!EDIT)return;const a=e.target.closest('[data-vadd]');const d=e.target.closest('[data-vdel]');if(!a&&!d)return;const [k,p]=(a||d).dataset[a?'vadd':'vdel'].split('|');
110	if(a){changeV(k,v=>{if(p==='r')v.rows.push(v.cols.map(()=>''));else{if(!v.histList)v.histList=histOf(v).map(x=>({...x}));v.histList.unshift({date:new Date().toISOString().slice(0,10),trkorr:'',user:'',text:''})}});rerender();if(p==='r'){const ti=Object.keys(tblKey).find(i=>tblKey[i]===k);if(ti!=null)fullTable(ti)}const v=D.views[k];const f=document.querySelector('[data-vk="'+CSS.escape(k)+'"][data-ve="'+(p==='r'?'r.'+(v.rows.length-1)+'.0':'h.0.trkorr')+'"]');if(f)f.focus();return}
111	const [kind,i]=p.split('.');changeV(k,v=>{if(kind==='r'){v.rows.splice(Number(i),1);shiftCust(v,Number(i),-1)}else{if(!v.histList)v.histList=histOf(v).map(x=>({...x}));v.histList.splice(Number(i),1)}});rerender()});
112	// Screenshots: a picked file or a pasted image replaces one drawing (overview or detail);
113	// wide captures are scaled to 1800 px so the saved page stays small.
114	let selMock=null;
115	function useShot(k,key,file){const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{let src=r.result;if(img.naturalWidth>1800){const c=document.createElement('canvas');c.width=1800;c.height=Math.round(img.naturalHeight*1800/img.naturalWidth);c.getContext('2d').drawImage(img,0,0,c.width,c.height);src=c.toDataURL('image/png')}changeV(k,v=>{v.shots={...(v.shots||{}),[key]:src}});rerender()};img.src=r.result};r.readAsDataURL(file)}
116	document.addEventListener('click',e=>{if(!EDIT)return;const m=e.target.closest('.mock');if(!m)return;e.stopPropagation();document.querySelectorAll('.mock.ce-sel').forEach(x=>x.classList.remove('ce-sel'));m.classList.add('ce-sel');const key=m.dataset.svg;selMock={k:key.replace(/#detail$/,''),key}},true);
117	document.addEventListener('click',e=>{if(!EDIT)return;const b=e.target.closest('[data-shot],[data-unshot]');if(!b)return;const [k,key]=(b.dataset.shot||b.dataset.unshot).split('|');
118	if(b.dataset.unshot){changeV(k,v=>{const s={...(v.shots||{})};delete s[key];v.shots=Object.keys(s).length?s:null});rerender();return}
119	const inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.addEventListener('change',()=>{if(inp.files[0])useShot(k,key,inp.files[0])});inp.click()});
120	document.addEventListener('paste',e=>{if(!EDIT||!selMock||e.target.closest&&e.target.closest('[contenteditable]'))return;for(const it of (e.clipboardData&&e.clipboardData.items)||[]){if(it.type.indexOf('image/')===0){e.preventDefault();useShot(selMock.k,selMock.key,it.getAsFile());return}}});
121	function setEdit(on){EDIT=on;document.body.classList.toggle('editing',on);$('#ce-edit').textContent=on?EL.done:EL.edit;rerender()}
122	$('#ce-edit').onclick=()=>setEdit(!EDIT);
123	$('#ce-undo').onclick=()=>doUndo();
124	function doUndo(){const u=undo.pop();if(!u)return;if(u.vk){const v=D.views[u.vk],b=JSON.parse(u.before);for(const f of VF)v[f]=b[f]??undefined;v.edited=b.edited??undefined;vtouched.add(u.vk);dirty=true;saveDraft();rerender();return}if(u.before==null)delete D.notes[u.id];else D.notes[u.id]=JSON.parse(u.before);touched.add(u.id);dirty=true;saveDraft();renderTree();rerender()}
125	document.addEventListener('keydown',e=>{if(EDIT&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.closest('[contenteditable]')){e.preventDefault();doUndo()}});
126	// Text fields: the note is written back when the field loses focus.
127	document.addEventListener('focusout',e=>{const el=EDIT&&e.target.closest&&e.target.closest('[contenteditable][data-ef]');const id=el&&el.dataset.a;if(!el||!id||!D.notes[id])return;const v=el.innerText.replace(/ /g,' ').replace(/\s+$/,'');const p=el.dataset.ef;if((getAt(D.notes[id],p)??'')===v)return;change(id,()=>setAt(D.notes[id],p,v))});
128	document.addEventListener('keydown',e=>{const el=EDIT&&e.target.closest&&e.target.closest('[contenteditable][data-ef]');if(el&&e.key==='Enter'){e.preventDefault();el.blur()}});
129	document.addEventListener('click',e=>{if(!EDIT||!cur)return;const a=e.target.closest('[data-add]');const d=e.target.closest('[data-del]');const nn=e.target.closest('[data-newnote]');
130	if(nn){change(cur,()=>{D.notes[cur]={purpose:'',impact:[],cautions:[],refs:[],sapdoc:'',cases:null,mix:'',compare:[],checklist:[],criteria:{},sources:[],review:'none',issues:[]}});renderTree();rerender();const f=document.querySelector('[data-ef="purpose"]');if(f)f.focus();return}
131	if(a){const p=a.dataset.add;change(cur,()=>{const l=getAt(D.notes[cur],p);if(Array.isArray(l))l.push('');else setAt(D.notes[cur],p,[''])});rerender();const l=getAt(D.notes[cur],p);const f=document.querySelector('[data-ef="'+p+'.'+(l.length-1)+'"]');if(f)f.focus();return}
132	if(d){const ks=d.dataset.del.split('.');const i=Number(ks.pop());const p=ks.join('.');change(cur,()=>getAt(D.notes[cur],p).splice(i,1));rerender()}});
133	window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=EL.unsaved}});
134	// Save: the page again, with every edit embedded; rendered parts are emptied so the file stays the original page.
135	$('#ce-save').onclick=()=>{const m=document.createElement('div');m.className='ce-modal ce-ui';let who='';try{who=localStorage.getItem('sc4sap-config-author')||''}catch(e){}
136	m.innerHTML='<div><h3>'+esc(EL.saveTitle)+'</h3><label>'+esc(EL.author)+'</label><input id="ce-who" value="'+esc(who)+'"><label>'+esc(EL.note)+'</label><textarea id="ce-note" rows="3">'+esc(EL.noteDefault)+'</textarea><div class="btns"><button id="ce-x">'+esc(EL.cancel)+'</button><button class="pri" id="ce-ok">'+esc(EL.ok)+'</button></div></div>';document.body.appendChild(m);
137	m.querySelector('#ce-x').onclick=()=>m.remove();m.querySelector('#ce-ok').onclick=()=>{const author=m.querySelector('#ce-who').value.trim();if(!author){alert(EL.needAuthor);return}try{localStorage.setItem('sc4sap-config-author',author)}catch(e){}const note=m.querySelector('#ce-note').value.trim();m.remove();download(author,note)}};
138	function download(author,note){const at=new Date().toISOString();const ids=[...touched].filter(id=>bare(D.notes[id])!==orig[id]);for(const id of ids){if(D.notes[id]){D.notes[id].edited={author,at};CE.edits[id]=D.notes[id]}else CE.edits[id]=null}const vids=[...vtouched].filter(k=>vbare(k)!==vorig[k]);for(const k of vids){const v=D.views[k];v.edited={author,at};CE.views[k]={...JSON.parse(vbare(k)),cols:v.cols.map(c=>c.name),edited:v.edited}}CE.system=D.meta.system;CE.module=D.meta.module;CE.log.push({author,at,note,activities:ids,views:vids});
139	const doc=document.documentElement.cloneNode(true);for(const s of ['#main','#ref','#tree'])doc.querySelector(s).innerHTML='';doc.querySelector('#count').textContent='';doc.querySelector('body').className='';doc.querySelectorAll('.ce-ui').forEach(x=>x.remove());doc.querySelector('#lb div').innerHTML='';doc.querySelector('#ce-edit').textContent=EL.edit;doc.querySelectorAll('.chip[aria-pressed]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.f==='all')));
140	doc.querySelector('#config-edits').textContent=JSON.stringify(CE).replace(/</g,'\\u003c');
141	const blob=new Blob(['<!doctype html>\n'+doc.outerHTML],{type:'text/html'});const a=document.createElement('a');const base=decodeURIComponent(location.pathname.split('/').pop()||'config.html');a.download=/-edited\.html$/.test(base)?base:base.replace(/\.html?$/i,'')+'-edited.html';a.href=URL.createObjectURL(blob);document.body.appendChild(a);a.click();a.remove();
142	dirty=false;touched.clear();vtouched.clear();undo.length=0;for(const k of Object.keys(orig))delete orig[k];for(const k of Object.keys(vorig))delete vorig[k];dropDraft();renderTree();rerender();alert(EL.saved)}
143	loadDraft().then(d=>{if(!d||!Object.keys(d.edits||{}).length&&!Object.keys(d.views||{}).length)return;const b=document.createElement('div');b.className='ce-draft ce-ui';b.innerHTML='<span>'+esc(EL.draft)+'</span><button data-r="1">'+esc(EL.resume)+'</button><button data-r="0">'+esc(EL.discard)+'</button>';document.body.appendChild(b);
144	b.onclick=e=>{const r=e.target.dataset.r;if(r==null)return;b.remove();if(r==='1'){for(const [k,e] of Object.entries(d.views||{})){if(!(k in vorig))vorig[k]=vbare(k);vapply(k,{...e,edited:{at:new Date(d.at).toISOString()}});if(D.views[k])D.views[k].svgStale=true;vtouched.add(k)}for(const [id,n] of Object.entries(d.edits||{})){if(!(id in orig))orig[id]=bare(D.notes[id]);if(n)D.notes[id]=keepSvg(n,D.notes[id]);else delete D.notes[id];touched.add(id)}dirty=true;renderTree();setEdit(true)}else dropDraft()}});
145	`;
