1	// SAP table reader for config-to-document.
2	//
3	// Talks to the sc4sap MCP server (bridge/mcp-server.cjs) over stdio and reads
4	// customizing tables with GetSqlQuery. On BASIS < 7.50 the server answers
5	// through ZMCP_ADT_DISPATCH TABLE_READ, which only reads customizing / system
6	// tables (delivery class C, G, E, S) and the transport key tables, so this
7	// reader never touches business data.
8	//
9	// Reads always use SELECT * and drop columns on this side: the dispatcher
10	// cannot select single fields that sit inside an .INCLUDE.
11	
12	import { resolve, dirname } from 'path';
13	import { fileURLToPath } from 'url';
14	import { Client } from '@modelcontextprotocol/sdk/client/index.js';
15	import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
16	
17	const __dirname = dirname(fileURLToPath(import.meta.url));
18	const ROOT = resolve(__dirname, '..', '..');
19	
20	// SC4SAP_MCP_BRIDGE points at another bridge (e.g. the installed plugin's)
21	// when the script runs from a source checkout.
22	const BRIDGE = process.env.SC4SAP_MCP_BRIDGE || resolve(ROOT, 'bridge', 'mcp-server.cjs');
23	
24	// Plain (T161) or namespaced (/BEV2/ED901) DDIC names, at most 30 characters.
25	export const TABLE_NAME_RE = /^(?=.{2,30}$)(\/[A-Z0-9_]+\/)?[A-Z][A-Z0-9_]*$/;
26	const MAX_ROWS = 5000;
27	
28	export async function connect(name = 'config-to-document') {
29	  const transport = new StdioClientTransport({ command: 'node', args: [BRIDGE], stderr: 'ignore' });
30	  const client = new Client({ name, version: '1.0.0' });
31	  await client.connect(transport);
32	  return client;
33	}
34	
35	function quote(v) {
36	  return `'${String(v).replace(/'/g, "''")}'`;
37	}
38	
39	/** WHERE text from { FIELD: value | [values] } — values are quoted, never spliced raw. */
40	export function whereOf(cond = {}) {
41	  const parts = [];
42	  for (const [field, value] of Object.entries(cond)) {
43	    if (!/^[A-Z][A-Z0-9_]*$/.test(field)) throw new Error(`bad field name ${field}`);
44	    if (Array.isArray(value)) {
45	      if (!value.length) return null;
46	      parts.push(`${field} IN (${value.map(quote).join(', ')})`);
47	    } else if (value && typeof value === 'object' && 'like' in value) {
48	      parts.push(`${field} LIKE ${quote(value.like)}`);
49	    } else {
50	      parts.push(`${field} = ${quote(value)}`);
51	    }
52	  }
53	  return parts.join(' AND ');
54	}
55	
56	/**
57	 * Read rows of one table. `where` is an object (see whereOf) or a raw
58	 * condition string built by the caller from trusted values only.
59	 * Returns { ok, rows, truncated, error }.
60	 */
61	export async function readTable(client, table, { where = '', fields = null, maxRows = MAX_ROWS } = {}) {
62	  if (!TABLE_NAME_RE.test(table)) return { ok: false, rows: [], error: `invalid table name ${table}` };
63	  const cond = typeof where === 'string' ? where : whereOf(where);
64	  if (cond === null) return { ok: true, rows: [] };
65	  const sql = `SELECT * FROM ${table}${cond ? ` WHERE ${cond}` : ''}`;
66	  const key = `${maxRows}|${sql}`;
67	  let out = client.cache?.get(key);
68	  if (!out) {
69	    out = await runSql(client, sql, maxRows);
70	    if (out.ok) client.cache?.set(key, out);
71	  }
72	  if (!fields || !out.ok) return out;
73	  const keep = fields.map((f) => f.toUpperCase());
74	  return { ...out, rows: out.rows.map((r) => Object.fromEntries(keep.map((k) => [k, r[k] ?? '']))) };
75	}
76	
77	async function runSql(client, sql, maxRows) {
78	  try {
79	    const res = await client.callTool({ name: 'GetSqlQuery', arguments: { sql_query: sql, row_number: maxRows } });
80	    const text = res?.content?.[0]?.text ?? '';
81	    if (res?.isError) return { ok: false, rows: [], error: text.slice(0, 400) };
82	    const data = JSON.parse(text);
83	    return { ok: true, rows: data.rows || [], truncated: !!data.truncated };
84	  } catch (e) {
85	    return { ok: false, rows: [], error: String(e?.message ?? e).slice(0, 400) };
86	  }
87	}
88	
89	/** Read with an IN list split into chunks so the WHERE text stays short. */
90	// TABLE_READ refuses any condition containing SELECT, JOIN or " FROM " — even
91	// inside a quoted value. Such values are read one by one through LIKE patterns
92	// that do not spell the word, so they cannot sink a whole chunk.
93	const GUARD = /SELECT|JOIN| FROM /i;
94	
95	export async function readIn(client, table, field, values, { extra = {}, fields = null, chunk = 40 } = {}) {
96	  const all = [...new Set(values.filter(Boolean))];
97	  const uniq = all.filter((v) => !GUARD.test(String(v)));
98	  const out = [];
99	  const errors = [];
100	  for (const v of all.filter((x) => GUARD.test(String(x)))) {
101	    const like = String(v).replace(/SELECT/gi, 'SELEC_').replace(/JOIN/gi, 'JOI_').replace(/ FROM /gi, ' FRO_ ');
102	    const r = await readTable(client, table, { where: { ...extra, [field]: { like } }, fields });
103	    if (r.ok) out.push(...r.rows.filter((row) => String(row[field]) === String(v)));
104	    else errors.push(r.error);
105	  }
106	  for (let i = 0; i < uniq.length; i += chunk) {
