}

async function ddicObject(client, name) {
  const t = await call(client, 'GetTable', { table_name: name });
  const td = inner(t, 'table_data');
  if (td?.fields?.length) return { kind: td.tabclass === 'VIEW' ? 'VIEW' : 'TABLE', def: td };
