      section, name: m[1].toUpperCase(), typing: m[2].toUpperCase().replace(/\s+/g, ' '), ref: m[3].toUpperCase(),
      optional: /\bOPTIONAL\b|\bDEFAULT\b/i.test(m[4]),
    });
  }
  return out;
}

