  const t = (MSG[lang] || MSG.en)[f.code] || f.code;
  return t.replace(/\{(\w+)\}/g, (_, k) => (f.args && f.args[k] != null ? f.args[k] : '')) + (f.code === 'REQ' ? ` (${f.path})` : '');
