// interface-mapping-spec — the document model and the operations on it.
//
// model.json (one per interface and language, next to the pages):
// {
//   schema: 1, ifId, lang, version, created,
//   header:   { name, summary, detail, transfer, trigger, cycle, cycleCount, perRun, recordSize,
//               relation, targetLogic, author, writtenAt },
//   sap:      { side: 'source' | 'target' | 'both', system, readAt,
//               source: { object, kind, lines }, target: { … } }      — what --refresh reads again
//   request:  { source: Side, target: Side, rows: Row[] }
//   response: null | { source: { object, structure, cardinality }, target: { … }, rows: Row[] }
//   rules:    [{ id: 'R1', text }], extract: [string], remarks, etc,
//   revisions:[{ seq, version, date, text, author, approver }]
// }
// Side = { system, module, region, owner, adapter, object, structure, cardinality }
// Row  = { no, s: Cell, r, t: Cell, map, proposed?, sync?: 'added' | 'changed' | 'removed', was? }
// Cell = { table, field, key, type, size, nul, desc, ddic? }

import { proposeDbType } from './if-codes.mjs';

export const emptyCell = () => ({ table: '', field: '', key: '', type: '', size: '', nul: '', desc: '' });
const ddicType = (c) => String(c?.ddic || '').split(' ')[0];
const ddicLen = (c) => String(c?.ddic || '').split(' ')[1] || c?.size || '';

export const today = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

export function nextVersion(v, major = false) {
  const [a, b] = String(v || '0.0').split('.').map((n) => Number(n) || 0);
  return major ? `${a + 1}.0` : `${a}.${b + 1}`;
}

/** A01, A02 … (B… for the response); renumbering carries every MAPPING along. */
export function renumber(rows, prefix) {
  const map = new Map();
  rows.forEach((r, i) => {
    const no = prefix + String(i + 1).padStart(2, '0');
    if (r.no) map.set(String(r.no).toUpperCase(), no);
    r.no = no;
  });
  for (const r of rows) if (r.map && map.has(String(r.map).toUpperCase())) r.map = map.get(String(r.map).toUpperCase());
  return rows;
}

/** The non-SAP side proposed from a SAP cell (decision 12): same name, DB type, same key / null / text. */
export function proposeCell(c) {
  const { type, size } = proposeDbType(ddicType(c) || c.type, ddicLen(c));
  return { table: '', field: c.field, key: c.key, type, size, nul: c.nul, desc: c.desc };
}

/**
 * Rows of one block from the SAP rows read for one or both sides.
 * sapSide 'source' | 'target': the other side is proposed and mapped 1:1.
 * 'both': target rows are matched to source rows by field name (proposed mapping).
 */
export function blockRows({ source = null, target = null }, prefix) {
  const rows = [];
  if (source && !target) for (const c of source) rows.push({ s: { ...c }, r: '', t: proposeCell(c), map: '', proposed: true });
  else if (target && !source) for (const c of target) rows.push({ s: proposeCell(c), r: '', t: { ...c }, map: '', proposed: true });
  else {
    for (const c of source || []) rows.push({ s: { ...c }, r: '', t: emptyCell(), map: '' });
    for (const c of target || []) {
      const hit = rows.find((r) => r.s.field === c.field && !r.t.field);
      if (hit) { hit.t = { ...c }; hit.proposed = true; } else rows.push({ s: emptyCell(), r: '', t: { ...c }, map: '' });
    }
  }
  renumber(rows, prefix);
  for (const r of rows) if (r.s.field && r.t.field) r.map = r.no;
  return rows;
}

const RESPONSE_PROPOSAL = {
  ko: [['XSTAT', '1', '처리 결과 — S: 성공, E: 실패'], ['XMSGS', '100', '처리 메시지']],
  en: [['XSTAT', '1', 'Result — S: success, E: error'], ['XMSGS', '100', 'Message']],
};

/** Response block proposal for a synchronous interface without function-module exports. */
export function proposedResponse(lang) {
  const cells = (RESPONSE_PROPOSAL[lang] || RESPONSE_PROPOSAL.en).map(([field, size, desc]) => ({ table: '', field, key: 'N', type: 'VARCHAR2', size, nul: 'N', desc }));
  const rows = cells.map((c) => ({ s: { ...c }, r: '', t: { ...c }, map: '', proposed: true }));
  renumber(rows, 'B');
  for (const r of rows) r.map = r.no;
  return { source: { object: '', structure: 'PARAMETER', cardinality: '1:1' }, target: { object: '', structure: 'PARAMETER', cardinality: '1:1' }, rows };
}

const emptySide = () => ({ system: '', module: '', region: '', owner: '', adapter: '', object: '', structure: '', cardinality: '' });

/**
 * A new model from the interview answers and the SAP read.
 * input = { ifId, lang, header, sides: { source, target }, sapSide, system,
 *           sap: { source?: SplitResult, target?: SplitResult }, objects: { source?, target? }, response?: bool }
 * SplitResult = splitGroups() of sap-fields.mjs.
 */
export function newModel(input) {
  const { ifId, lang = 'ko', header = {}, sides = {}, sapSide = 'source', sap = {}, objects = {}, system = '' } = input;
  const m = {
    schema: 1, ifId: String(ifId).trim(), lang, version: '0.1', created: today(),
    header: { name: '', summary: '', detail: '', transfer: '', trigger: '', cycle: '', cycleCount: '', perRun: '', recordSize: '', relation: '', targetLogic: '', author: '', writtenAt: today(), ...header },
    sap: { side: sapSide, system, readAt: new Date().toISOString(), source: objects.source || null, target: objects.target || null },
    request: { source: { ...emptySide(), ...(sides.source || {}) }, target: { ...emptySide(), ...(sides.target || {}) }, rows: [] },
    response: null, rules: [], extract: [], remarks: '', etc: '', revisions: [],
  };
  m.request.rows = blockRows({ source: sap.source?.request.rows, target: sap.target?.request.rows }, 'A');
  for (const side of ['source', 'target']) {
    const s = sap[side];
    if (!s) continue;
    m.request[side].object ||= objects[side]?.object || '';
    m.request[side].structure ||= s.request.shape;
  }
  const res = { source: sap.source?.response?.rows, target: sap.target?.response?.rows };
  if (res.source || res.target) {
    m.response = { source: { object: '', structure: '', cardinality: '' }, target: { object: '', structure: '', cardinality: '' }, rows: blockRows(res, 'B') };
    for (const side of ['source', 'target']) {
      const r = sap[side]?.response;
      if (r) { m.response[side].object = objects[side]?.object || ''; m.response[side].structure = r.shape; }
    }
  } else if (input.response || header.transfer === 'SYNC') m.response = proposedResponse(lang);
  m.revisions.push({ seq: 1, version: '0.1', date: today(), text: lang === 'ko' ? '최초 작성' : 'First version', author: header.author || '', approver: '' });
  return m;
}

const SAP_KEYS = ['table', 'field', 'key', 'type', 'size', 'nul', 'desc', 'ddic'];

/**
 * --refresh: the SAP side read again (decision 14). User content stays; SAP
 * cells are updated, new fields appended with a proposal, removed ones marked.
 * fresh = { source?: SplitResult, target?: SplitResult }. Returns counts.
 */
export function refreshModel(m, fresh) {
  const counts = { added: 0, changed: 0, removed: 0 };
  for (const [bk, prefix] of [['request', 'A'], ['response', 'B']]) {
    for (const [side, sd, other] of [['source', 's', 't'], ['target', 't', 's']]) {
      const f = fresh[side];
      if (!f) continue;
      const rowsNew = bk === 'request' ? f.request.rows : f.response?.rows;
      if (!rowsNew) continue;
      if (!m[bk]) m[bk] = { source: { object: '', structure: '', cardinality: '' }, target: { object: '', structure: '', cardinality: '' }, rows: [] };
      const b = m[bk];
      for (const r of b.rows) { if (r.sync) { delete r.sync; delete r.was; } }
      const id = (c) => `${c.table}|${c.field}`.toUpperCase();
      const freshById = new Map(rowsNew.map((c) => [id(c), c]));
      const seen = new Set();
      for (const r of b.rows) {
        const c = r[sd];
        if (!c || !c.field) continue;
        const n = freshById.get(id(c));
        if (!n) { r.sync = 'removed'; counts.removed++; continue; }
        seen.add(id(c));
        const diff = SAP_KEYS.filter((k) => String(c[k] ?? '') !== String(n[k] ?? ''));
        if (diff.length) { r.was = Object.fromEntries(diff.map((k) => [k, c[k] ?? ''])); r[sd] = { ...c, ...n }; r.sync = 'changed'; counts.changed++; }
      }
      for (const n of rowsNew) {
        if (seen.has(id(n))) continue;
        const row = { [sd]: { ...n }, r: '', [other]: proposeCell(n), map: '', proposed: true, sync: 'added' };
        b.rows.push(row);
        counts.added++;
      }
      renumber(b.rows, prefix);
      for (const r of b.rows) if (r.sync === 'added' && !r.map) r.map = r.no;
    }
  }
  return counts;
}

// ── English companion: the free texts out and back in ─────────────────────

const getAt = (o, p) => p.split('.').reduce((x, k) => (x == null ? x : x[k]), o);
const setAt = (o, p, v) => { const ks = p.split('.'); const last = ks.pop(); ks.reduce((x, k) => x[k], o)[last] = v; };

/** Paths of every translatable text with its value (names, codes, SQL and objects stay). */
export function textsOf(m) {
  const paths = ['header.name', 'header.summary', 'header.detail', 'header.targetLogic', 'header.recordSize', 'remarks', 'etc'];
  for (const bk of ['request', 'response']) (m[bk]?.rows || []).forEach((r, i) => { for (const sd of ['s', 't']) paths.push(`${bk}.rows.${i}.${sd}.desc`); });
  (m.rules || []).forEach((_, i) => paths.push(`rules.${i}.text`));
  (m.revisions || []).forEach((_, i) => paths.push(`revisions.${i}.text`));
  const out = {};
  for (const p of paths) { const v = getAt(m, p); if (typeof v === 'string' && v.trim()) out[p] = v; }
  return out;
}

/** The companion model: a copy of `m` with the translated texts; paths it does not know are ignored. */
export function withTexts(m, lang, texts) {
  const c = structuredClone(m);
  c.lang = lang;
  for (const [p, v] of Object.entries(texts || {})) if (typeof v === 'string' && getAt(c, p) !== undefined) setAt(c, p, v);
  return c;
}

