    ifId: 'Interface ID', name: 'Interface name', summary: 'Summary', detail: 'Details', transfer: 'Transfer mode',
    trigger: 'Trigger', cycle: 'Cycle', cycleCount: 'Runs per cycle', perRun: 'Records per run',
