  },
};
export const pageLabels = (lang) => LABELS[String(lang || '').slice(0, 2)] || LABELS.en;

const STYLE = `
:root{--ink:#1d2d3e;--ink2:#475e75;--mute:#8396a8;--line:#c9d3dd;--soft:#f3f6f9;--head:#dfe8f1;--accent:#0a6ed1;--err:#bb0000;--warn:#c35500;--info:#0a6ed1;--prop:#eef6ff;--added:#e8f6ea;--changed:#fff6db;--removed:#fbeaea}
