        rule = { id: `R${n}`, text: ruleText(kind, m.lang), kind, proposed: true };
        (m.rules ||= []).push(rule);
        byKind.set(kind, rule);
        added++;
      }
      r.r = rule.id;
    }
  }
  return added;
}

