      const nz = Number(String(z.size || '').split(',')[0]);
      if (na > 0 && nz > 0 && nz < na) out.push({ sev: 'warn', code: 'TRUNC', path: p + '.' + to + '.size', args: { no: r.no, from: na, to: nz } });
      const fa = ifTypeFamilies(a.type, a.ddic);
