      if (fa.length && fz.length && !fa.some((x) => fz.includes(x))) out.push({ sev: 'warn', code: 'TYPE_MISMATCH', path: p + '.' + to + '.type', args: { no: r.no, from: a.type, to: z.type } });
    });
