const FM_SRC = `FUNCTION Z_RFC_DEMO\r
  IMPORTING\r
    VALUE(I_WERKS) TYPE WERKS_D\r
    VALUE(I_DATE) LIKE SY-DATUM OPTIONAL\r
  EXPORTING\r
    VALUE(E_SUBRC) TYPE SYSUBRC\r
  TABLES\r
    IT_ITEMS STRUCTURE ZDEMO_ITEM\r
