const fs = require('fs');
const root = process.argv[2];
const after = (file, marker, line) => {
  const p = root + '/' + file;
  const lines = fs.readFileSync(p, 'utf8').split('\n');
  const i = lines.findIndex((l) => l.includes(marker));
  if (i < 0) throw new Error(file + ': marker not found ' + marker);
  const end = lines.slice(i + 1).findIndex((l) => !l.startsWith(' ') || l.trim() === '');
  // insert right after the marker line (single-line entries) unless a block follows (skill-model section)
  lines.splice(i + 1, 0, line);
  fs.writeFileSync(p, lines.join('\n'));
};

