    if (!hit) continue;
    const { ref, ...cell } = hit;
    r[sd] = { ...cell, desc: c.desc || cell.desc };
    n++;
    const o = sd === 's' ? 't' : 's';
    if (!sides.includes(o) && !r[o]?.field) { r[o] = proposeCell(r[sd]); r.map ||= r.no; r.proposed = true; }
  }
  proposeRules(m);
  return n;
}

const SAP_KEYS = ['table', 'field', 'key', 'type', 'size', 'nul', 'desc', 'ddic'];

