111	/** SAP side of each side: an object (table, structure, view, FM) or, for a new interface, a field list. */
112	async function sapRead(objects, extraLines = {}, fields = {}) {
113	  return withClient(async (client) => {
114	    const out = {};
115	    const problems = [];
116	    for (const side of ['source', 'target']) {
117	      const o = objects?.[side];
118	      if (!o?.object && fields?.[side]?.length) {
119	        const r = await resolveRefs(client, fields[side]);
120	        out[side] = { request: { rows: r.rows.map(({ ref, ...c }) => c), shape: 'TABLE' }, response: null, kind: 'FIELDS' };
121	        problems.push(...r.problems.map((p) => `${side}: ${p}`));
122	        continue;
123	      }
124	      if (!o?.object) continue;
125	      const r = await readSapObject(client, o.object, { kind: o.kind, lines: { ...(o.lines || {}), ...extraLines } });
126	      if (r.error) { problems.push(`${side}: ${r.error}`); continue; }
127	      out[side] = splitGroups(r);
128	      out[side].kind = r.kind;
129	      if (r.unresolved?.length) problems.push(...r.unresolved.map((u) => `${side}: ${u.param} (${u.ref}) — ${u.why}`));
130	    }
