  [`const body=rows.map((r,i)=>{const p=bk+'.rows.'+i;`, `const body=rows.map((r,i)=>{const p=bk+'.rows.'+i;const sy=['added','changed','removed'].includes(r.sync)?r.sync:'';`],
  [`(r.sync?'<span class="bdg '+r.sync[0]+'">'+esc(L[r.sync])+'</span>':'')`, `(sy?'<span class="bdg '+sy[0]+'">'+esc(L[sy])+'</span>':'')`],
  [`[r.proposed?'prop':'',r.sync?'sync-'+r.sync:''].join(' ')`, `[r.proposed?'prop':'',sy?'sync-'+sy:''].join(' ')`],
]);
