1	// interface-mapping-spec — the document model and the operations on it.
2	//
3	// model.json (one per interface and language, next to the pages):
4	// {
5	//   schema: 1, ifId, lang, version, created,
6	//   header:   { name, summary, detail, transfer, trigger, cycle, cycleCount, perRun, recordSize,
7	//               relation, targetLogic, author, writtenAt },
8	//   sap:      { side: 'source' | 'target' | 'both', system, readAt,
9	//               source: { object, kind, lines }, target: { … } }      — what --refresh reads again
10	//   request:  { source: Side, target: Side, rows: Row[] }
11	//   response: null | { source: { object, structure, cardinality }, target: { … }, rows: Row[] }
12	//   rules:    [{ id: 'R1', text }], extract: [string], remarks, etc,
13	//   revisions:[{ seq, version, date, text, author, approver }]
14	// }
15	// Side = { system, module, region, owner, adapter, object, structure, cardinality }
16	// Row  = { no, s: Cell, r, t: Cell, map, proposed?, sync?: 'added' | 'changed' | 'removed', was? }
17	// Cell = { table, field, key, type, size, nul, desc, ddic? }
18	
19	import { proposeDbType, PRESETS, ruleKind, ruleText } from './if-codes.mjs';
20	
21	export const emptyCell = () => ({ table: '', field: '', key: '', type: '', size: '', nul: '', desc: '' });
22	const ddicType = (c) => String(c?.ddic || '').split(' ')[0];
23	const ddicLen = (c) => String(c?.ddic || '').split(' · ')[0].split(' ')[1] || c?.size || '';
24	
25	export const today = () => {
26	  const d = new Date();
27	  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
28	};
29	
30	export function nextVersion(v, major = false) {
31	  const [a, b] = String(v || '0.0').split('.').map((n) => Number(n) || 0);
32	  return major ? `${a + 1}.0` : `${a}.${b + 1}`;
33	}
34	
35	/** A01, A02 … (B… for the response); renumbering carries every MAPPING along. */
36	export function renumber(rows, prefix) {
37	  const map = new Map();
38	  rows.forEach((r, i) => {
39	    const no = prefix + String(i + 1).padStart(2, '0');
40	    if (r.no) map.set(String(r.no).toUpperCase(), no);
41	    r.no = no;
42	  });
43	  for (const r of rows) if (r.map && map.has(String(r.map).toUpperCase())) r.map = map.get(String(r.map).toUpperCase());
44	  return rows;
45	}
46	
47	/** The non-SAP side proposed from a SAP cell (decision 12): same name, DB type, same key / null / text. */
48	export function proposeCell(c) {
49	  const { type, size } = proposeDbType(ddicType(c) || c.type, ddicLen(c));
50	  return { table: '', field: c.field, key: c.key, type, size, nul: c.nul, desc: c.desc };
51	}
52	
53	/**
54	 * Rows of one block from the SAP rows read for one or both sides.
55	 * sapSide 'source' | 'target': the other side is proposed and mapped 1:1.
56	 * 'both': target rows are matched to source rows by field name (proposed mapping).
57	 */
58	export function blockRows({ source = null, target = null }, prefix) {
59	  const rows = [];
60	  if (source && !target) for (const c of source) rows.push({ s: { ...c }, r: '', t: proposeCell(c), map: '', proposed: true });
61	  else if (target && !source) for (const c of target) rows.push({ s: proposeCell(c), r: '', t: { ...c }, map: '', proposed: true });
62	  else {
63	    for (const c of source || []) rows.push({ s: { ...c }, r: '', t: emptyCell(), map: '' });
64	    for (const c of target || []) {
65	      const hit = rows.find((r) => r.s.field === c.field && !r.t.field);
66	      if (hit) { hit.t = { ...c }; hit.proposed = true; } else rows.push({ s: emptyCell(), r: '', t: { ...c }, map: '' });
67	    }
68	  }
69	  renumber(rows, prefix);
70	  for (const r of rows) if (r.s.field && r.t.field) r.map = r.no;
71	  return rows;
72	}
73	
74	const RESPONSE_PROPOSAL = {
75	  ko: [['XSTAT', '1', '처리 결과 — S: 성공, E: 실패'], ['XMSGS', '100', '처리 메시지']],
76	  en: [['XSTAT', '1', 'Result — S: success, E: error'], ['XMSGS', '100', 'Message']],
77	};
78	
79	/** Response block proposal for a synchronous interface without function-module exports. */
80	export function proposedResponse(lang) {
81	  const cells = (RESPONSE_PROPOSAL[lang] || RESPONSE_PROPOSAL.en).map(([field, size, desc]) => ({ table: '', field, key: 'N', type: 'VARCHAR2', size, nul: 'N', desc }));
82	  const rows = cells.map((c) => ({ s: { ...c }, r: '', t: { ...c }, map: '', proposed: true }));
83	  renumber(rows, 'B');
84	  for (const r of rows) r.map = r.no;
85	  return { source: { object: '', structure: 'PARAMETER', cardinality: '1:1' }, target: { object: '', structure: 'PARAMETER', cardinality: '1:1' }, rows };
86	}
87	
88	const emptySide = () => ({ system: '', module: '', region: '', owner: '', adapter: '', object: '', structure: '', cardinality: '' });
89	
90	/**
91	 * A new model from the interview answers and the SAP read.
92	 * input = { ifId, lang, header, sides: { source, target }, sapSide, system,
93	 *           sap: { source?: SplitResult, target?: SplitResult }, objects: { source?, target? }, response?: bool }
94	 * SplitResult = splitGroups() of sap-fields.mjs.
95	 */
96	export function newModel(input) {
97	  const preset = PRESETS[input.preset] || null;
98	  const { ifId, lang = 'ko', sides = {}, sap = {}, objects = {}, system = '' } = input;
99	  const sapSide = input.sapSide || preset?.sapSide || 'source';
100	  const header = { ...(preset?.header || {}), ...(input.header || {}) };
101	  const side = (k) => ({ ...emptySide(), ...(preset?.side || {}), ...(preset?.adapter?.[k] ? { adapter: preset.adapter[k] } : {}), ...(sides[k] || {}) });
102	  const m = {
103	    schema: 1, ifId: String(ifId).trim(), lang, version: '0.1', created: today(), ...(input.preset ? { preset: input.preset } : {}),
104	    header: { name: '', summary: '', detail: '', transfer: '', trigger: '', cycle: '', cycleCount: '', perRun: '', recordSize: '', relation: '', targetLogic: '', author: '', writtenAt: today(), ...header },
105	    sap: { side: sapSide, system, readAt: new Date().toISOString(), source: objects.source || null, target: objects.target || null },
106	    request: { source: side('source'), target: side('target'), rows: [] },
107	    response: null, rules: [], extract: [], remarks: '', etc: '', revisions: [],
108	  };
109	  m.request.rows = blockRows({ source: sap.source?.request.rows, target: sap.target?.request.rows }, 'A');
110	  for (const side of ['source', 'target']) {
111	    const s = sap[side];
112	    if (!s) continue;
113	    m.request[side].object ||= objects[side]?.object || '';
114	    if (objects[side]?.object || !m.request[side].structure) m.request[side].structure = s.request.shape;
115	  }
116	  const res = { source: sap.source?.response?.rows, target: sap.target?.response?.rows };
117	  if (res.source || res.target) {
118	    m.response = { source: { object: '', structure: '', cardinality: '' }, target: { object: '', structure: '', cardinality: '' }, rows: blockRows(res, 'B') };
119	    for (const side of ['source', 'target']) {
120	      const r = sap[side]?.response;
121	      if (r) { m.response[side].object = objects[side]?.object || ''; m.response[side].structure = r.shape; }
122	    }
123	    // The other side receives the same shape; occurrence as in the request.
124	    const shape = (sap.source || sap.target)?.response?.shape || '';
125	    for (const side of ['source', 'target']) {
126	      m.response[side].structure ||= shape;
127	      m.response[side].cardinality ||= m.request[side].cardinality || '';
128	    }
129	  } else if (input.response ?? (preset ? preset.response : header.transfer === 'SYNC')) m.response = proposedResponse(lang);
130	  proposeRules(m);
131	  m.revisions.push({ seq: 1, version: '0.1', date: today(), text: lang === 'ko' ? '최초 작성' : 'First version', author: header.author || '', approver: '' });
132	  return m;
133	}
134	
135	/**
136	 * Conversion rules proposed from the SAP field types (decision 20): one rule
137	 * per kind (date, time, leading zeros, currency, quantity), linked from every
138	 * proposed row that needs it. Rules the user already has are reused by kind.
139	 */
140	export function proposeRules(m) {
141	  const sapSide = m.sap?.side;
142	  if (!sapSide || sapSide === 'both') return 0;
143	  const sd = sapSide === 'source' ? 's' : 't';
144	  const byKind = new Map((m.rules || []).filter((r) => r.kind).map((r) => [r.kind, r]));
145	  let added = 0;
146	  for (const [bk, out] of [['request', sapSide === 'source'], ['response', sapSide !== 'source']]) {
147	    for (const r of m[bk]?.rows || []) {
148	      if (!r.proposed || r.r) continue;
149	      const kind = ruleKind(r[sd], out);
150	      if (!kind) continue;
151	      let rule = byKind.get(kind);
152	      if (!rule) {
153	        const n = Math.max(0, ...(m.rules || []).map((x) => Number(String(x.id).replace(/\D/g, '')) || 0)) + 1;
154	        rule = { id: `R${n}`, text: ruleText(kind, m.lang), kind, proposed: true };
155	        (m.rules ||= []).push(rule);
156	        byKind.set(kind, rule);
157	        added++;
158	      }
159	      r.r = rule.id;
160	    }
161	  }
162	  return added;
163	}
164	
165	const refOf = (c) => {
166	  const f = String(c.field || '').trim().toUpperCase();
167	  if (f.includes('-')) return f;
168	  return c.table ? `${String(c.table).trim().toUpperCase()}-${f}` : f;
169	};
170	
171	/** SAP-side cells typed by hand (TABLE-FIELD or a data element) that DDIC has not filled yet. */
172	export function pendingRefs(m) {
173	  const sides = m.sap?.side === 'both' ? ['s', 't'] : [m.sap?.side === 'target' ? 't' : 's'];
174	  const out = new Set();
175	  for (const bk of ['request', 'response']) for (const r of m[bk]?.rows || []) for (const sd of sides) {
176	    const c = r[sd];
177	    if (c?.field && !c.ddic) out.add(refOf(c));
178	  }
179	  return [...out];
180	}
181	
182	/**
183	 * Fill those cells from the DDIC rows read for them (resolveRefs of sap-fields.mjs):
184	 * type, size, key, null and the DDIC note; a description the user wrote stays.
185	 * An empty other side gets the usual proposal. Returns the number of cells filled.
186	 */
187	export function resolveModel(m, resolved) {
188	  const byRef = new Map((resolved || []).map((c) => [c.ref, c]));
189	  const sides = m.sap?.side === 'both' ? ['s', 't'] : [m.sap?.side === 'target' ? 't' : 's'];
190	  let n = 0;
191	  for (const bk of ['request', 'response']) for (const r of m[bk]?.rows || []) for (const sd of sides) {
192	    const c = r[sd];
193	    if (!c?.field || c.ddic) continue;
194	    const hit = byRef.get(refOf(c));
195	    if (!hit) continue;
196	    const { ref, ...cell } = hit;
197	    r[sd] = { ...cell, desc: c.desc || cell.desc, key: c.key || cell.key, nul: c.nul || cell.nul };
198	    n++;
199	    const o = sd === 's' ? 't' : 's';
200	    if (!sides.includes(o) && !r[o]?.field) { r[o] = proposeCell(r[sd]); r.map ||= r.no; r.proposed = true; }
201	  }
202	  proposeRules(m);
203	  return n;
204	}
205	
206	// What SAP decides about a field. Key, null and description stay as the user left them.
207	const SAP_KEYS = ['type', 'size', 'ddic'];
208	
209	/**
210	 * --refresh: the SAP side read again (decision 14). User content stays; SAP
211	 * cells are updated, new fields appended (with a proposal when the other side
212	 * is not SAP), fields gone from SAP marked. Only cells that came from SAP
213	 * (`ddic` set) are compared. A field already marked removed is not counted
214	 * again, so an unchanged system gives all-zero counts.
215	 * fresh = { source?: SplitResult, target?: SplitResult }. Returns counts.
216	 */
217	export function refreshModel(m, fresh) {
218	  const counts = { added: 0, changed: 0, removed: 0 };
219	  const both = m.sap?.side === 'both';
220	  for (const [bk, prefix] of [['request', 'A'], ['response', 'B']]) {
221	    const sides = [['source', 's', 't'], ['target', 't', 's']].filter(([side]) => (bk === 'request' ? fresh[side]?.request?.rows : fresh[side]?.response?.rows));
222	    if (!sides.length) continue;
223	    if (!m[bk]) m[bk] = { source: { object: '', structure: '', cardinality: '' }, target: { object: '', structure: '', cardinality: '' }, rows: [] };
224	    const b = m[bk];
225	    const wasRemoved = new Map();
226	    for (const r of b.rows) { if (r.sync) wasRemoved.set(r, r.sync === 'removed' ? r.sync : null); delete r.sync; delete r.was; }
227	    for (const [side, sd, other] of sides) {
228	      const rowsNew = bk === 'request' ? fresh[side].request.rows : fresh[side].response.rows;
229	      const id = (c) => `${c.table}|${c.field}`.toUpperCase();
230	      const freshById = new Map(rowsNew.map((c) => [id(c), c]));
231	      const seen = new Set();
232	      for (const r of b.rows) {
233	        const c = r[sd];
234	        if (!c?.field || !c.ddic || r.sync === 'added') continue;
235	        const n = freshById.get(id(c));
236	        if (!n) { r.sync = 'removed'; if (wasRemoved.get(r) !== 'removed') counts.removed++; continue; }
237	        seen.add(id(c));
238	        const diff = SAP_KEYS.filter((k) => String(c[k] ?? '') !== String(n[k] ?? ''));
239	        if (diff.length) {
240	          r.was = Object.fromEntries(diff.map((k) => [k, c[k] ?? '']));
241	          r[sd] = { ...c, type: n.type, size: n.size, ddic: n.ddic, ...(n.dom ? { dom: n.dom } : {}) };
242	          r.sync = 'changed';
243	          counts.changed++;
244	        }
245	      }
246	      for (const n of rowsNew) {
247	        if (seen.has(id(n))) continue;
248	        const row = { [sd]: { ...n }, r: '', [other]: both ? emptyCell() : proposeCell(n), map: '', sync: 'added', ...(both ? {} : { proposed: true }) };
249	        b.rows.push(row);
250	        counts.added++;
251	      }
252	    }
253	    renumber(b.rows, prefix);
254	    if (!both) for (const r of b.rows) if (r.sync === 'added' && !r.map) r.map = r.no;
255	  }
256	  proposeRules(m);
257	  return counts;
258	}
259	
260	// ── English companion: the free texts out and back in ─────────────────────
261	
262	const getAt = (o, p) => p.split('.').reduce((x, k) => (x == null ? x : x[k]), o);
263	const setAt = (o, p, v) => { const ks = p.split('.'); const last = ks.pop(); ks.reduce((x, k) => x[k], o)[last] = v; };
264	
265	/** Paths of every translatable text with its value (names, codes, SQL and objects stay). */
266	export function textsOf(m) {
267	  const paths = ['header.name', 'header.summary', 'header.detail', 'header.targetLogic', 'header.recordSize', 'remarks', 'etc'];
268	  for (const bk of ['request', 'response']) (m[bk]?.rows || []).forEach((r, i) => { for (const sd of ['s', 't']) paths.push(`${bk}.rows.${i}.${sd}.desc`); });
269	  (m.rules || []).forEach((_, i) => paths.push(`rules.${i}.text`));
270	  (m.revisions || []).forEach((_, i) => paths.push(`revisions.${i}.text`));
271	  const out = {};
272	  for (const p of paths) { const v = getAt(m, p); if (typeof v === 'string' && v.trim()) out[p] = v; }
273	  return out;
274	}
275	
276	/** The companion model: a copy of `m` with the translated texts; paths it does not know are ignored. */
277	export function withTexts(m, lang, texts) {
278	  const c = structuredClone(m);
279	  c.lang = lang;
280	  c.companionOf = m.lang;
281	  for (const [p, v] of Object.entries(texts || {})) if (typeof v === 'string' && getAt(c, p) !== undefined) setAt(c, p, v);
282	  return c;
283	}
284

