199	    const o = sd === 's' ? 't' : 's';
200	    if (!sides.includes(o) && !r[o]?.field) { r[o] = proposeCell(r[sd]); r.map ||= r.no; r.proposed = true; }
201	  }
202	  proposeRules(m);
203	  return n;
204	}
205	
206	// What SAP decides about a field. Key, null and description stay as the user left them.
207	const SAP_KEYS = ['type', 'size', 'ddic'];
208	
209	/**
210	 * --refresh: the SAP side read again (decision 14). User content stays; SAP
211	 * cells are updated, new fields appended (with a proposal when the other side
212	 * is not SAP), fields gone from SAP marked. Only cells that came from SAP
213	 * (`ddic` set) are compared. A field already marked removed is not counted
214	 * again, so an unchanged system gives all-zero counts.
215	 * fresh = { source?: SplitResult, target?: SplitResult }. Returns counts.
216	 */
217	export function refreshModel(m, fresh) {
218	  const counts = { added: 0, changed: 0, removed: 0 };
219	  const both = m.sap?.side === 'both';
220	  for (const [bk, prefix] of [['request', 'A'], ['response', 'B']]) {
