 * parameters named as outputs go to the response block (the page shows the
 * split; the user moves rows if the naming misled it).
 */
export function splitGroups(sap) {
  const req = [];
  const res = [];
  for (const g of sap.groups || []) (g.section === 'EXPORTING' || (g.section === 'TABLES' && OUT_TABLE_RE.test(g.name)) ? res : req).push(g);
