const fs = require('fs');
const dir = process.argv[2];
const patch = (file, pairs) => {
  let s = fs.readFileSync(dir + '/' + file, 'utf8');
  for (const [a, b] of pairs) {
    if (!s.includes(a)) throw new Error(file + ' missing: ' + a.slice(0, 90));
    s = s.split(a).join(b);
  }
  fs.writeFileSync(dir + '/' + file, s);
};

