// Drives the generated page in headless Chrome over CDP and checks edit mode.
import { spawn } from 'child_process';
import { writeFileSync, mkdtempSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';

const [, , pageUrl, outFile] = process.argv;
const profile = mkdtempSync(join(tmpdir(), 'ifcdp-'));
const chrome = spawn('C:/Program Files/Google/Chrome/Application/chrome.exe',
  ['--headless=new', '--disable-gpu', '--remote-debugging-port=9333', `--user-data-dir=${profile}`, '--window-size=1500,1200', 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let targets;
for (let i = 0; i < 40; i++) { try { targets = await (await fetch('http://127.0.0.1:9333/json')).json(); if (targets.length) break; } catch {} await sleep(250); }
const t = targets.find((x) => x.type === 'page');
const ws = new WebSocket(t.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id = 0; const pending = new Map(); const logs = [];
ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } if (m.method === 'Runtime.exceptionThrown') logs.push('EXC ' + JSON.stringify(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text)); if (m.method === 'Runtime.consoleAPICalled') logs.push(m.params.args.map((a) => a.value).join(' ')); };
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails)); return r.result.result.value; };
await send('Runtime.enable');
await send('Page.enable');
await send('Page.navigate', { url: pageUrl });
await sleep(1500);
const results = {};
const check = (name, ok, detail) => { results[name] = ok ? 'ok' : 'FAIL ' + JSON.stringify(detail); };

const n0 = await ev(`ifValidate(D).filter(f=>f.sev!=='info').length`);
await ev(`document.querySelector('#ie-edit').click()`);
check('edit on', await ev(`document.body.classList.contains('editing') && !!document.querySelector('[contenteditable][data-p="header.summary"]')`));
// text edit
await ev(`(()=>{const el=document.querySelector('[data-p="header.summary"]');el.dispatchEvent(new FocusEvent('focusin',{bubbles:true}));el.innerText='구매오더 생성 시 외부로 송신';el.dispatchEvent(new FocusEvent('focusout',{bubbles:true}));})()`);
await sleep(100);
check('text commit', (await ev(`D.header.summary`)) === '구매오더 생성 시 외부로 송신', await ev('D.header.summary'));
check('findings drop', (await ev(`ifValidate(D).filter(f=>f.sev!=='info').length`)) === n0 - 1);
// select edit
await ev(`(()=>{const s=document.querySelector('select[data-p="header.cycle"]');s.value='DAY';s.dispatchEvent(new Event('change',{bubbles:true}));})()`);
check('select commit', (await ev(`D.header.cycle`)) === 'DAY');
check('cycleCount required', await ev(`ifValidate(D).some(f=>f.path==='header.cycleCount')`));
// row delete renumbers + mapping follows
await ev(`document.querySelector('button[data-row="request|0|del"]').click()`);
check('row delete', JSON.stringify(await ev(`D.request.rows.map(r=>r.no+'>'+r.map)`)) === JSON.stringify(['A01>A01', 'A02>A02']), await ev(`D.request.rows.map(r=>r.no+'>'+r.map)`));
// paste a block from Excel
await ev(`(()=>{const el=document.querySelector('[data-p="request.rows.1.t.field"]');el.focus();const dt=new DataTransfer();dt.setData('text/plain','PO_NO\\tY\\tvarchar2\\t10\\nPO_ITEM\\tY\\tNUMBER\\t5\\n');el.dispatchEvent(new ClipboardEvent('paste',{clipboardData:dt,bubbles:true,cancelable:true}));})()`);
check('paste', JSON.stringify(await ev(`D.request.rows.slice(1).map(r=>[r.no,r.t.field,r.t.key,r.t.type,r.t.size,!!r.proposed])`)) === JSON.stringify([['A02', 'PO_NO', 'Y', 'VARCHAR2', '10', false], ['A03', 'PO_ITEM', 'Y', 'NUMBER', '5', false]]), await ev(`D.request.rows.map(r=>[r.no,r.t.field,r.t.key,r.t.type,r.t.size])`));
check('unmapped warns', await ev(`ifValidate(D).some(f=>f.code==='UNMAPPED'&&f.args.no==='A03')`));
// undo the paste
await ev(`document.querySelector('#ie-undo').click()`);
check('undo', (await ev(`D.request.rows.length`)) === 2);
// rule edit clears its proposal
await ev(`(()=>{const el=document.querySelector('[data-p="rules.0.text"]');el.dispatchEvent(new FocusEvent('focusin',{bubbles:true}));el.innerText='앞자리 0 제거 후 전송';el.dispatchEvent(new FocusEvent('focusout',{bubbles:true}));})()`);
await sleep(100);
check('rule confirmed', (await ev(`!D.rules[0].proposed`)) === true);
// response block add
await ev(`document.querySelector('button[data-resp="1"]').click()`);
check('response added', await ev(`!!D.response && D.response.rows[0].no==='B01' && !!document.querySelector('[data-p="response.rows.0.s.field"]')`));
// draft saved in IndexedDB
await sleep(300);
check('draft', await ev(`new Promise(r=>{const q=indexedDB.open('sc4sap-if-spec',1);q.onsuccess=()=>{const g=q.result.transaction('drafts').objectStore('drafts').getAll();g.onsuccess=()=>r(g.result.length===1)}})`));
// save: capture the download
await ev(`(()=>{window.__blob=null;URL.createObjectURL=b=>{window.__blob=b;return 'blob:x'};window.alert=()=>{};HTMLAnchorElement.prototype.click=function(){window.__name=this.download};})()`);
await ev(`document.querySelector('#ie-save').click()`);
await ev(`(()=>{document.querySelector('#ie-who').value='Tester';document.querySelector('#ie-appr').value='Lead';document.querySelector('#ie-ok').click();})()`);
await sleep(200);
const saved = await ev(`window.__blob.text()`);
writeFileSync(outFile, saved);
check('save name', (await ev(`window.__name`)) === 'MM00010-v0.2-ko-edited.html', await ev('window.__name'));
check('save revision', JSON.stringify(await ev(`D.revisions.at(-1)`)).includes('"approver":"Lead"'));
check('saved page clean', !saved.includes('class="editing"') && saved.includes('"version":"0.2"') && saved.includes('"baseVersion":"0.1"'));
check('no exceptions', logs.filter((l) => l.startsWith('EXC')).length === 0, logs);
console.log(JSON.stringify(results, null, 1));
ws.close(); chrome.kill();

